package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public final class VibrationEditor {
 final Context c;final JSONObject draft;final Button entry;final Handler h=new Handler();Dialog dialog;LinearLayout body;TextView status,pad;Button record;boolean recording,holding,ownPlayback;long started,changed;long[] chosen;String chosenName;final ArrayList<Long> segments=new ArrayList<>();final ArrayList<View> customViews=new ArrayList<>();int bg,fg,accent,card,onAccent;
 static int color(Context c,String name,int fallback){try{Class<?> p=Class.forName("mx.jorge.despierta.Palette");java.lang.reflect.Constructor<?> ctor=p.getDeclaredConstructor(Context.class);ctor.setAccessible(true);Object palette=ctor.newInstance(c);java.lang.reflect.Field field=p.getDeclaredField(name);field.setAccessible(true);return field.getInt(palette);}catch(Exception e){return fallback;}}
 int dp(int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 VibrationEditor(Context c,JSONObject d,Button b){this.c=c;draft=d;entry=b;chosen=VibrationPattern.read(d);chosenName=d.optString("vibrationName","Clásica");bg=color(c,"surface",0xff17392e);fg=color(c,"fg",Color.WHITE);accent=color(c,"accent",0xffb9ef96);card=color(c,"card",0xff294237);onAccent=color(c,"onAccent",0xff10241e);}
 public static void attach(Context c,LinearLayout page,JSONObject draft){Button button=new Button(c);button.setAllCaps(false);button.setBackgroundTintList(null);button.setTextColor(color(c,"fg",Color.WHITE));GradientDrawable g=new GradientDrawable();g.setColor(color(c,"surface",0xff17392e));g.setCornerRadius(30);button.setBackground(g);button.setText("Patrón de vibración · "+draft.optString("vibrationName","Clásica")+"  ›");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,12);page.addView(button,lp);button.setOnClickListener(v->{if(PatternPlayer.ringing()){Toast.makeText(c,"Detén el aviso antes de editar la vibración",Toast.LENGTH_SHORT).show();return;}new VibrationEditor(c,draft,button).show();});}
 TextView text(String s,int size){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(fg);t.setPadding(0,dp(8),0,dp(8));return t;}
 Button button(String s,boolean primary,Runnable run){Button b=new Button(c);b.setAllCaps(false);b.setBackgroundTintList(null);b.setText(s);b.setTextColor(primary?onAccent:fg);GradientDrawable g=new GradientDrawable();g.setColor(primary?accent:card);g.setCornerRadius(dp(18));b.setBackground(g);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.topMargin=dp(7);body.addView(b,lp);b.setOnClickListener(v->run.run());return b;}
 void show(){dialog=new Dialog(c);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);body=new LinearLayout(c);body.setOrientation(1);body.setPadding(dp(20),dp(16),dp(20),dp(20));GradientDrawable g=new GradientDrawable();g.setColor(bg);g.setCornerRadius(dp(26));body.setBackground(g);ScrollView scroll=new ScrollView(c);scroll.addView(body);dialog.setContentView(scroll);body.addView(text("Tu vibración",23));body.addView(text("Elige un patrón o graba tus pulsaciones. Se repetirá durante el aviso.",14));
 for(int i=0;i<VibrationPattern.NAMES.length;i++){final int k=i;button(VibrationPattern.NAMES[i]+(chosenName.equals(VibrationPattern.NAMES[i])?"  ✓":""),false,()->{stopRecording();stopPreview();chosen=VibrationPattern.PRESETS[k].clone();chosenName=VibrationPattern.NAMES[k];saveChoice();});}
 button("Personalizado"+(chosenName.equals("Personalizado")?"  ✓":""),false,()->{for(View v:customViews)v.setVisibility(View.VISIBLE);resize();begin();});
 status=text("Elegido: "+chosenName,15);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status);customViews.add(status);
 pad=text("Mantén pulsado aquí\nSuelta para marcar las pausas",18);pad.setGravity(Gravity.CENTER);pad.setBackgroundColor(card);body.addView(pad,new LinearLayout.LayoutParams(-1,dp(135)));pad.setOnTouchListener((v,event)->touch(event));customViews.add(pad);
 record=button("Grabar de nuevo",true,()->{if(recording)stopRecording();else begin();});customViews.add(record);
 customViews.add(button("Probar una vez",false,()->{stopRecording();stopPreview();if(PatternPlayer.ringing())return;PatternPlayer.play(c,chosen,false);ownPlayback=true;status.setText("Probando: "+chosenName);}));
 customViews.add(button("Detener prueba",false,()->{stopPreview();status.setText("Elegido: "+chosenName);}));
 customViews.add(button("Guardar personalizado",true,()->{stopRecording();if(!chosenName.equals("Personalizado")){status.setText("Primero graba tu patrón");return;}saveChoice();}));
 for(View v:customViews)v.setVisibility(View.GONE);
 button("Cancelar",false,()->dialog.dismiss());dialog.setOnDismissListener(d->{h.removeCallbacksAndMessages(null);recording=false;stopPreview();});dialog.show();Window w=dialog.getWindow();w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.setGravity(Gravity.BOTTOM);resize();}
 void saveChoice(){try{JSONArray a=new JSONArray();for(long n:VibrationPattern.validate(chosen))a.put(n);draft.put("vibrationPattern",a);draft.put("vibrationName",chosenName);entry.setText("Patrón de vibración · "+chosenName+"  ›");dialog.dismiss();}catch(Exception e){status.setText("Graba al menos un pulso");}}
 void resize(){int width=c.getResources().getDisplayMetrics().widthPixels,max=(int)(c.getResources().getDisplayMetrics().heightPixels*.82);body.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));dialog.getWindow().setLayout(-1,Math.min(max,body.getMeasuredHeight()));}

 void stopPreview(){if(ownPlayback&&!PatternPlayer.ringing()){Vibrator v=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);if(v!=null)v.cancel();}ownPlayback=false;}
 void begin(){stopPreview();segments.clear();segments.add(0L);started=SystemClock.elapsedRealtime();changed=started;holding=false;recording=true;record.setText("Terminar grabación");status.setText("Grabando · toca y suelta el recuadro (máximo 20 s)");h.postDelayed(()->stopRecording(),20000);}
 boolean touch(MotionEvent e){if(!recording)return true;long now=SystemClock.elapsedRealtime();if(e.getActionMasked()==MotionEvent.ACTION_DOWN&&!holding){if(segments.size()>1)segments.add(Math.max(1,now-changed));holding=true;changed=now;pad.getParent().requestDisallowInterceptTouchEvent(true);pad.setBackgroundColor(accent);pad.setTextColor(onAccent);Vibrator v=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);if(v!=null&&!PatternPlayer.ringing()){PatternPlayer.hold(c,Math.max(1,20000-(now-started)));ownPlayback=true;}}else if((e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)&&holding){segments.add(Math.max(40,now-changed));holding=false;changed=now;pad.getParent().requestDisallowInterceptTouchEvent(false);pad.setBackgroundColor(card);pad.setTextColor(fg);stopPreview();if(segments.size()>=79||now-started>=19500)stopRecording();}return true;}
 void stopRecording(){if(!recording)return;h.removeCallbacksAndMessages(null);if(holding){segments.add(Math.max(40,SystemClock.elapsedRealtime()-changed));holding=false;}recording=false;pad.getParent().requestDisallowInterceptTouchEvent(false);stopPreview();pad.setBackgroundColor(card);pad.setTextColor(fg);record.setText("Volver a grabar");try{chosen=VibrationPattern.recorded(segments);chosenName="Personalizado";status.setText("Personalizado listo · "+((segments.size()-1)/2+1)+" pulsos. Prueba antes de guardar.");}catch(Exception e){status.setText("No se grabó ningún pulso. Inténtalo de nuevo.");}}
}
